// RolePermission 描述可分配给网页登录角色的业务操作。
type RolePermission struct {
	ID        string   `json:"id"`        // 权限标识。
	Label     string   `json:"label"`     // 操作名称。
	Category  string   `json:"category"`  // 所属模块。
	Read      bool     `json:"read"`      // 是否属于常规只读权限。
	Sensitive bool     `json:"sensitive"` // 是否涉及敏感内容。
	Routes    []string `json:"-"`         // 精确登记的接口。
}

